 @override Widget build(BuildContext c)=>Stack(children:[ListView(padding:const EdgeInsets.fromLTRB(18,18,18,96),children:[Row(children:[Text('${items.length} Temuan',style:const TextStyle(fontWeight:FontWeight.w800,color:navy,fontSize:16)),const Spacer(),TextButton.icon(onPressed:busy?null:_sync,icon:busy?const SizedBox(width:16,height:16,child:CircularProgressIndicator(strokeWidth:2)):const Icon(Icons.cloud_upload_outlined),label:const Text('Sinkron'))]),if(items.isEmpty)const Padding(padding:EdgeInsets.only(top:48),child:Column(children:[Icon(Icons.fact_check_outlined,size:48,color:blue),SizedBox(height:12),Text('Belum ada temuan',style:TextStyle(fontWeight:FontWeight.w800)),Text('Tambahkan temuan hasil inspeksi.',style:TextStyle(color:muted))]))else ...items.map((t)=>Container(margin:const EdgeInsets.only(bottom:12),padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(16),border:Border.all(color:line)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(t.kodeTemuan,style:const TextStyle(fontWeight:FontWeight.w800,color:blue))),Text(t.prioritas,style:const TextStyle(fontSize:11,fontWeight:FontWeight.w800))]),const SizedBox(height:8),Text(t.temuan,style:const TextStyle(fontSize:16,fontWeight:FontWeight.w800,color:navy)),const SizedBox(height:4),Text('${t.tier} • ${t.segmen}',style:const TextStyle(color:muted,fontSize:12))]))]),Positioned(right:18,bottom:20,child:FloatingActionButton.extended(onPressed:_add,backgroundColor:amber,foregroundColor:navy,icon:const Icon(Icons.add),label:const Text('Temuan',style:TextStyle(fontWeight:FontWeight.w800))))]);
