 @override void initState(){super.initState();_init();}
 Future<void>_init()async{kode=await repo.kodeBaru(widget.wo.kodeWo);object=repo.jenisObject(widget.sesi);listMaster=await repo.master('List_Temuan');pohonMaster=await repo.master('Jenis Pohon');if(mounted)setState((){});}
