 @override Widget build(BuildContext c)=>Scaffold(backgroundColor:const Color(0xFFF1F5F9),appBar:AppBar(backgroundColor:blue,foregroundColor:Colors.white,title:const Text('Tambah Temuan',style:TextStyle(fontWeight:FontWeight.w800))),body:ListView(padding:const EdgeInsets.all(18),children:[_info('Kode WO',widget.wo.kodeWo),_info('Kode Temuan',kode.isEmpty?'Menyiapkan...':kode),_info('Penyulang',widget.wo.penyulang),_info('Section',widget.wo.section),_field(segmen,'Segmen *'),const SizedBox(height:12),if(object.isEmpty)_drop('Jenis Object *',['Jaringan','Gardu'],object,(v)=>setState(()=>object=v!))else _info('Jenis Object',object),_drop('Tier *',['Tier 1','Tier 2'],tier,(v)=>setState((){tier=v!;temuan='';})),_drop('Temuan *',temuanOptions,temuan,(v)=>setState(()=>temuan=v!)),if(object=='Jaringan')_field(jarak,'Jarak Terhadap Jaringan (m) *',number:true),if(vegetasi)...[_drop('Jenis Pohon *',pohonMaster.map((r)=>_pick(r,['Jenis Pohon','Pohon','Nama'])).where((x)=>x.isNotEmpty).toSet().toList(),pohon,(v)=>setState(()=>pohon=v!)),_field(tinggi,'Tinggi Pohon (m) *',number:true)],const SizedBox(height:12),OutlinedButton.icon(onPressed:_gps,icon:const Icon(Icons.my_location),label:Text(gps==null?'Ambil Koordinat Temuan':'Akurasi ${gps!.accuracyLabel}')),const SizedBox(height:8),OutlinedButton.icon(onPressed:()async{final v=await _camera('Foto Temuan');if(mounted)setState(()=>foto=v);},icon:const Icon(Icons.camera_alt),label:Text(foto.isEmpty?'Ambil Foto Temuan':'Foto Temuan siap')),const SizedBox(height:8),OutlinedButton.icon(onPressed:()async{final v=await _camera('Foto Lingkungan');if(mounted)setState(()=>lingkungan=v);},icon:const Icon(Icons.camera_alt),label:Text(lingkungan.isEmpty?'Ambil Foto Lingkungan':'Foto Lingkungan siap')),const SizedBox(height:20),ElevatedButton(onPressed:saving?null:_save,style:ElevatedButton.styleFrom(backgroundColor:amber,foregroundColor:navy,minimumSize:const Size.fromHeight(52)),child:Text(saving?'Menyimpan...':'Simpan Temuan',style:const TextStyle(fontWeight:FontWeight.w800)))]));
 Widget _info(String a,String b)=>Padding(padding:const EdgeInsets.only(bottom:12),child:InputDecorator(decoration:InputDecoration(labelText:a,filled:true,fillColor:Colors.white,border:OutlineInputBorder(borderRadius:BorderRadius.circular(12),borderSide:const BorderSide(color:line))),child:Text(b.isEmpty?'-':b,style:const TextStyle(fontWeight:FontWeight.w700))));
 Widget _field(TextEditingController c,String l,{bool number=false})=>Padding(padding:const EdgeInsets.only(bottom:12),child:TextField(controller:c,keyboardType:number?const TextInputType.numberWithOptions(decimal:true):TextInputType.text,decoration:InputDecoration(labelText:l,filled:true,fillColor:Colors.white,border:OutlineInputBorder(borderRadius:BorderRadius.circular(12)))));
 Widget _drop(String l,List<String>o,String v,ValueChanged<String?>f)=>Padding(padding:const EdgeInsets.only(bottom:12),child:DropdownButtonFormField<String>(initialValue:o.contains(v)?v:null,items:o.map((x)=>DropdownMenuItem(value:x,child:Text(x,overflow:TextOverflow.ellipsis))).toList(),onChanged:f,isExpanded:true,decoration:InputDecoration(labelText:l,filled:true,fillColor:Colors.white,border:OutlineInputBorder(borderRadius:BorderRadius.circular(12)))));
}